 void applySnapshot(String raw)throws Exception{org.json.JSONObject j=new org.json.JSONObject(raw);android.content.SharedPreferences.Editor e=prefs.edit();for(String k:prefs.getAll().keySet())if(!k.startsWith("design:")&&!k.startsWith("usage:"))e.remove(k);Iterator<String> it=j.keys();while(it.hasNext()){String k=it.next();if(k.startsWith("design:")||k.startsWith("usage:")||k.equals("wallpaper"))continue;Object v=j.get(k);if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof String)e.putString(k,(String)v);}e.apply();recreate();}
